INSERT INTO paper_submission (name, company, paper_title, first_author, contact_number, contact_email, abstract, keywords, contribution_id, paper_status, reject_reason, email_status, deduction_status, discount_code) VALUES
('张伟明', '北京同仁医院眼科中心', '基于OCT血管成像的糖尿病视网膜病变早期微血管改变定量分析', '张伟明', '13800138001', 'zhangwm@trh-eye.cn', '目的：探讨OCT血管成像（OCTA）定量参数在糖尿病视网膜病变（DR）早期诊断中的价值。方法：纳入DR患者120例及健康对照60例，采用OCTA测量黄斑区浅层及深层毛细血管丛血管密度（VD）和中心凹无血管区面积（FAZ）。结果：DR组浅层VD显著低于对照组（P<0.01），FAZ面积显著增大（P<0.001）。结论：OCTA定量参数可作为DR早期微血管损害的敏感生物标志物。', 'OCT血管成像;糖尿病视网膜病变;血管密度;中心凹无血管区', 1001, '1', NULL, 0, '0', NULL),
('李秀芳', '中山眼科中心', '角膜塑形镜联合低浓度阿托品对青少年近视进展的协同控制效果', '李秀芳', '13900139002', 'lixf@gzoas.ac.cn', '目的：评估角膜塑形镜（OK镜）联合0.01%阿托品滴眼液对青少年近视进展的协同控制效果。方法：将150例8-14岁中重度近视青少年随机分为OK镜组、阿托品组和联合组，随访2年，比较眼轴增长和屈光度变化。结果：联合组眼轴增长（0.18±0.09mm/年）显著低于OK镜组（0.28±0.11mm/年）和阿托品组（0.35±0.13mm/年）（P<0.05）。结论：OK镜联合低浓度阿托品具有协同近视控制效果，为临床优化方案提供依据。', '角膜塑形镜;阿托品;近视控制;青少年近视;眼轴', 1002, '1', NULL, 0, '0', NULL),
('王建国', '上海复旦大学附属眼耳鼻喉科医院', '飞秒激光辅助白内障超声乳化术后角膜内皮细胞丢失率的两年随访研究', '王建国', '13700137003', 'wangjg@fdeent.org.cn', '目的：比较飞秒激光辅助白内障手术（FLACS）与传统超声乳化术（PHACO）对角膜内皮细胞的长期影响。方法：前瞻性队列研究，纳入年龄相关性白内障患者200例240眼，FLACS组120眼，PHACO组120眼，术后随访24个月。结果：术后3个月FLACS组内皮细胞丢失率（7.2%）显著低于PHACO组（10.8%）（P<0.05），至24个月两组差异缩小但仍有统计学意义。结论：FLACS在保护角膜内皮细胞方面具有短期优势，适合内皮储备较低的患者。', '飞秒激光;白内障;角膜内皮细胞;超声乳化', 1003, '1', NULL, 0, '0', NULL),
('陈晓燕', '温州医科大学附属眼视光医院', '多焦点软性接触镜对近视儿童调节功能与眼表健康的影响', '陈晓燕', '13600136004', 'chenxy@eye.ac.cn', '目的：评估多焦点软性接触镜（MFCL）长期佩戴对近视儿童调节功能和眼表健康的影响。方法：纳入8-12岁近视儿童80例，佩戴MFCL 18个月，分别于基线及每6个月评估调节幅度、调节灵活度、泪膜破裂时间（BUT）和角膜荧光素染色。结果：调节幅度较基线下降0.5D（P>0.05），BUT从12.3s降至9.8s（P<0.05），轻度角膜点状染色发生率15%。结论：MFCL对调节功能影响轻微，但需关注长期佩戴的眼表改变，建议配合人工泪液使用。', '多焦点接触镜;近视;调节功能;泪膜破裂时间;眼表', 1004, '1', NULL, 0, '0', NULL),
('刘志强', '浙江大学医学院附属第二医院眼科中心', '青光眼微创手术MIGS联合白内障手术的中期疗效与安全性评价', '刘志强', '13500135005', 'liuzq@z2eye.com', '目的：评价小梁网微旁路支架（iStent inject）联合超声乳化白内障手术治疗中度开角型青光眼的中期疗效。方法：纳入POAG合并白内障患者90例90眼，随机分为联合组（iStent+PHACO）和单纯PHACO组，随访36个月。结果：联合组术后36个月眼压较基线下降5.8mmHg（降幅28%），降压药物使用数从2.3种降至0.8种，均显著优于对照组（P<0.01）。结论：iStent inject联合白内障手术中期降眼压效果确切、安全性良好，可减少药物依赖。', '青光眼;微创青光眼手术;iStent;白内障;眼压', 1005, '1', NULL, 0, '0', NULL),
('赵雅琴', '天津市眼科医院', '先天性白内障术后视觉发育随访及弱视综合治疗疗效分析', '赵雅琴', '13400134006', 'yaqin.zhao@tjeye.cn', '目的：分析先天性白内障术后视觉发育规律及弱视综合治疗的疗效。方法：回顾性分析68例（112眼）先天性白内障手术患儿，术后随访3-8年，评估视力发育轨迹及遮盖+精细目力训练的弱视治疗效果。结果：术后5年最佳矫正视力≥0.5者占72%，早期手术（<6月龄）组视力预后显著优于晚期手术组（P<0.01）。结论：先天性白内障应尽早手术，术后规范弱视综合治疗可显著改善视觉发育预后。', '先天性白内障;弱视;视觉发育;儿童眼科', 1006, '1', NULL, 0, '0', NULL),
('孙鹏飞', '四川省人民医院眼科', '高度近视黄斑劈裂玻璃体切除术后视网膜微结构变化的OCT随访研究', '孙鹏飞', '13300133007', 'sunpf@scph.org', '目的：利用频域OCT观察高度近视黄斑劈裂（MF）玻璃体切除（PPV）术后视网膜微结构变化及与视力的相关性。方法：纳入高度近视MF患者45例45眼，PPV联合内界膜剥除，术前及术后1、3、6、12个月行OCT扫描。结果：术后6个月黄斑中心凹厚度从526μm降至238μm（P<0.001），外层视网膜完整性恢复者视力改善更显著（r=0.62）。结论：PPV治疗高度近视MF效果良好，术后外层视网膜结构完整性是视力恢复的关键预测因素。', '高度近视;黄斑劈裂;玻璃体切除;光学相干断层扫描', 1007, '1', NULL, 0, '0', NULL),
('周丽华', '哈尔滨医科大学附属第一医院眼科', '干眼症患者泪液中炎症因子表达与角膜神经密度变化的关联性研究', '周丽华', '13200132008', 'zhoulh@hrbmu.edu.cn', '目的：探讨干眼症患者泪液炎症因子水平与角膜神经密度变化的关联。方法：纳入中重度干眼患者60例及健康对照40例，采用IVCM测量角膜上皮下神经密度，ELISA检测泪液IL-6、IL-8、TNF-α水平。结果：干眼组神经密度（14246±3128μm/mm²）显著低于对照组（19873±2856μm/mm²）（P<0.001），IL-6与神经密度呈显著负相关（r=-0.58）。结论：泪液炎症因子升高与角膜神经退行性改变密切相关，抗炎治疗或可改善神经功能。', '干眼症;角膜神经;炎症因子;共聚焦显微镜', 1008, '1', NULL, 0, '0', NULL),
('吴海涛', '广东省人民医院眼科', '25G微创玻璃体切除手术治疗孔源性视网膜脱离的临床疗效及预后因素分析', '吴海涛', '13100131009', 'wuht@gdph.org.cn', '目的：分析25G经睫状体平坦部玻璃体切除（PPV）治疗孔源性视网膜脱离（RRD）的解剖复位率及视力预后因素。方法：回顾性纳入RRD患者160例160眼，均行25G PPV联合硅油或气体填充，随访12个月。结果：一次手术解剖复位率93.1%，最终复位率97.5%；术前黄斑未脱离、病程<7天者术后视力≥0.3的比例显著更高（P<0.01）。结论：25G PPV治疗RRD复位率高，早期手术及黄斑未脱离是视力预后保护因素。', '视网膜脱离;玻璃体切除;25G;预后因素', 1009, '2', NULL, 2, '1', 'MCLA-2026-0001'),
('郑文静', '北京大学人民医院眼科', '人工智能辅助糖尿病视网膜病变筛查系统在社区人群中的应用与卫生经济学评价', '郑文静', '13000130010', 'zhengwj@pkuph.edu.cn', '目的：评估AI辅助DR筛查系统在社区筛查中的应用效果及成本效益。方法：在6个社区卫生服务中心部署AI眼底照片分析系统，筛查糖尿病患者5200例，以眼科专家阅片为金标准评价诊断效能，并进行成本效益分析。结果：AI系统敏感度92.3%、特异度88.7%，DR检出率18.6%；与人工筛查相比，人均筛查成本降低42%，每避免一例视力损害的增量成本效益比优于传统模式。结论：AI辅助DR社区筛查具有良好诊断效能和卫生经济学价值，适合大规模推广。', '人工智能;糖尿病视网膜病变;社区筛查;卫生经济学', 1010, '2', NULL, 2, '1', 'MCLA-2026-0002'),
('黄志远', '华中科技大学同济医学院附属协和医院眼科', '有晶状体眼人工晶状体植入术矫正超高度近视的五年临床随访', '黄志远', '18900189011', 'huangzy@hust.edu.cn', '目的：评估有晶状体眼后房型人工晶状体（ICL V4c）植入矫正超高度近视的5年安全性及有效性。方法：纳入超高度近视（-10.00~-20.00D）患者110例210眼，行ICL V4c植入，随访60个月。结果：术后5年屈光度在±0.50D内占85.7%，裸眼视力较术前最佳矫正视力提升1行以上者占62%；内皮细胞5年丢失率4.8%，无白内障、青光眼等严重并发症。结论：ICL V4c矫正超高度近视长期效果稳定、安全性良好，内皮细胞丢失在可接受范围。', '有晶状体眼人工晶状体;超高度近视;ICL;长期随访', 1011, '2', NULL, 2, '1', 'MCLA-2026-0003'),
('林美玲', '厦门大学附属厦门眼科中心', '新型巩膜交联技术控制青少年近视进展的初步临床研究', '林美玲', '18800188012', 'linml@xmu-eye.cn', '目的：评估新型非侵入性巩膜交联（SXL）技术控制青少年近视进展的安全性与初步疗效。方法：纳入10-14岁进展性近视青少年40例，随机分为SXL治疗组（n=20）和对照组（n=20），随访18个月。结果：SXL组眼轴增长0.11±0.06mm/年，显著低于对照组0.29±0.10mm/年（P<0.01），治疗过程无严重不良反应。结论：非侵入性巩膜交联技术显示出良好的近视控制潜力，为近视干预提供了新思路，需扩大样本进一步验证。', '巩膜交联;近视控制;青少年;眼轴', 1012, '2', NULL, 2, '1', 'MCLA-2026-0004'),
('徐天宇', '山东省眼科研究所', '真菌性角膜炎共聚焦显微镜诊断与靶向抗真菌治疗的临床路径优化', '徐天宇', '18700187013', 'xuty@sd-eyes.org', '目的：优化基于IVCM的真菌性角膜炎早期诊断及靶向治疗临床路径。方法：纳入疑似真菌性角膜炎患者85例，对比IVCM诊断与角膜刮片培养结果，并根据IVCM菌丝形态指导初始用药方案。结果：IVCM诊断敏感度91.4%、特异度86.7%，平均确诊时间较培养缩短3.2天；靶向治疗组治愈时间（21.5天）显著短于经验治疗组（28.7天）（P<0.05）。结论：IVCM引导的早期诊断与靶向治疗路径可显著缩短真菌性角膜炎确诊及治愈时间。', '真菌性角膜炎;共聚焦显微镜;靶向治疗;临床路径', 1013, '2', NULL, 2, '1', 'MCLA-2026-0005'),
('何雪梅', '重庆医科大学附属第一医院眼科', '视网膜静脉阻塞黄斑水肿抗VEGF不同给药方案的疗效与经济性比较', '何雪梅', '18600186014', 'hexm@cqmu.edu.cn', '目的：比较抗VEGF药物三种给药方案（PRN、T&E、固定3+PRN）治疗RVO-ME的疗效与经济性。方法：纳入RVO-ME患者135例，随机分入三组，随访24个月，评估视力改善、注射次数及直接医疗费用。结果：T&E组视力提升（+14.2字母）与3+PRN组（+13.8字母）相当，均优于PRN组（+9.5字母）（P<0.05）；T&E组注射次数最少（8.2次），人均总费用最低。结论：T&E方案在RVO-ME治疗中疗效与经济性均衡最优，推荐作为首选方案。', '视网膜静脉阻塞;黄斑水肿;抗VEGF;治疗经济学', 1014, '2', NULL, 2, '1', 'MCLA-2026-0006'),
('郭建军', '西安交通大学第一附属医院眼科', '老视矫正型三焦点人工晶状体植入术后的视觉质量与脱镜率评估', '郭建军', '18500185015', 'guojj@xjtu.edu.cn', '目的：评估三焦点IOL（PanOptix）植入后的全程视力、视觉质量及脱镜率。方法：纳入双侧白内障植入三焦点IOL患者75例150眼，术后6个月评估远中近视力、对比敏感度、调制传递函数（MTF）及患者满意度问卷。结果：术后6个月远、中、近视力≥0.8的比例分别为96%、91%、83%；脱镜率89%，光晕发生率11%但满意度评分仍达4.3/5。结论：三焦点IOL可提供优异的全程视力及高脱镜率，适合有脱镜需求的老视白内障患者。', '三焦点人工晶状体;老视;视觉质量;脱镜率', 1015, '2', NULL, 2, '1', 'MCLA-2026-0007'),
('马小红', '昆明医科大学第一附属医院眼科', '翼状胬肉切除联合自体角膜缘干细胞移植术后复发的危险因素分析', '马小红', '18400184016', 'maxh@kmmu.edu.cn', '目的：分析翼状胬肉切除联合自体角膜缘干细胞移植（LSCT）术后复发的危险因素。方法：回顾性纳入原发性翼状胬肉患者320例，均行胬肉切除+LSCT，随访24个月，Logistic回归分析复发危险因素。结果：总体复发率6.9%；多因素分析显示年龄<50岁（OR=2.8）、胬肉侵入角膜>3mm（OR=3.5）、术后紫外线暴露（OR=2.2）为独立复发危险因素。结论：胬肉切除联合LSCT复发率低，对年轻、大胬肉患者应加强术后紫外线防护并密切随访。', '翼状胬肉;角膜缘干细胞移植;复发;危险因素', 1016, '3', '论文摘要研究设计存在缺陷：样本量计算依据不足，且对照组设置不合理，无法支持结论。建议完善研究设计后重新投稿。', 2, '0', NULL),
('杨春光', '南京医科大学附属眼科医院', '玻璃体腔注射地塞米松植入剂治疗葡萄膜炎性黄斑水肿的回顾性分析', '杨春光', '18300183017', 'yangcg@njmu-eye.cn', '目的：评估0.7mg地塞米松玻璃体内植入剂（Ozurdex）治疗非感染性葡萄膜炎性黄斑水肿（UME）的疗效。方法：纳入UME患者42例52眼，玻璃体腔注射Ozurdex，按需重复注射，随访12个月。结果：首次注射后1个月黄斑中心凹厚度从485μm降至278μm（P<0.001），视力提升9.2个字母；6个月疗效减退需重复注射，平均注射1.8次；眼压升高>10mmHg发生率13.5%。结论：Ozurdex治疗UME起效快、疗效确切，但需监测眼压，适合短期控制炎症性ME。', '葡萄膜炎;黄斑水肿;地塞米松植入剂;玻璃体腔注射', 1017, '3', '数据完整性不足：随访期间失访率超过20%，影响结果可靠性；且未交代是否合并使用全身免疫抑制剂。请补充完整随访数据后重新投稿。', 2, '0', NULL),
('罗志刚', '中南大学湘雅医院眼科', '甲状腺相关眼病眼眶减压术的手术时机选择与疗效对比研究', '罗志刚', '18200182018', 'luozg@xiangya.com', '目的：比较活动期与非活动期甲状腺相关眼病（TAO）行眼眶减压术的疗效差异，探讨最佳手术时机。方法：纳入中重度TAO患者65例，活动期手术组30例、非活动期组35例，比较术后突眼度回退、复视改善及并发症。结果：非活动期组突眼度回退（4.8mm）与活动期组（4.5mm）无显著差异，但活动期组术后一过性炎症反应及新发复视率更高（P<0.05）。结论：建议TAO病情稳定后行眼眶减压术，活动期手术需谨慎评估风险收益比。', '甲状腺相关眼病;眼眶减压术;手术时机;突眼', 1018, '3', '研究方法描述过于简略，关键手术技术细节（减压骨窗范围、脂肪切除量）未量化，结果可重复性差。建议按规范格式详细补充手术方法后重新投稿。', 2, '0', NULL),
('高慧敏', '安徽医科大学第一附属医院眼科', '儿童间歇性外斜视手术治疗的远期双眼视功能重建效果', '高慧敏', '18100181019', 'gaohm@ahmu.edu.cn', '目的：评估间歇性外斜视（IXT）患儿手术治疗后远期双眼视功能重建效果。方法：纳入IXT患儿98例，行双眼外直肌后徙或单眼后徙-截除术，术前及术后2年评估立体视、融合范围及眼位。结果：术后2年眼位正位率86.7%，立体视改善率78%，术前发病年龄<4岁者立体视恢复率显著更高（P<0.05）。结论：IXT应尽早手术干预，术前年龄小、立体视基础好者远期双眼视功能重建效果更佳。', '间歇性外斜视;双眼视功能;立体视;儿童斜视', 1019, '3', '论文选题与本次会议主题相关性不足，且研究样本中包含的手术方式不统一，异质性大，影响结论说服力。建议聚焦单一术式并突出与会议主题的关联后重新投稿。', 2, '0', NULL),
('邓伟杰', '深圳市眼科医院', '泪道内窥镜辅助下微创泪道再造术治疗复杂性泪道阻塞的临床观察', '邓伟杰', '18000180020', 'dengwj@sz-eyes.com', '目的：观察泪道内窥镜辅助微创泪道再造术治疗复杂性泪道阻塞的疗效。方法：纳入复杂性泪道阻塞患者55例60眼，在泪道内窥镜直视下精准去除阻塞病变并放置引流管，随访18个月。结果：术后18个月通畅率88.3%，较传统泪道探通+置管术（65.0%）显著提高（P<0.05）；手术并发症少，无严重不良反应。结论：泪道内窥镜辅助微创再造术治疗复杂性泪道阻塞成功率高、创伤小，值得临床推广。', '泪道阻塞;泪道内窥镜;微创手术;泪道再造', 1020, '3', '摘要中对照组数据来源未说明（前瞻性还是历史对照），统计方法描述不完整，P值未标注具体检验方法。请规范统计学报告格式后重新投稿。', 2, '0', NULL);